#include "protocol.h"
#include <string.h>
static void put32(uint8_t*p,uint32_t x){memcpy(p,&x,4);}static uint32_t get32(const uint8_t*p){uint32_t x;memcpy(&x,p,4);return x;}uint16_t protocol_crc16(const uint8_t*d,size_t n){uint16_t c=0xffff;for(size_t i=0;i<n;i++){c^=(uint16_t)d[i]<<8;for(int b=0;b<8;b++)c=(c&0x8000)?(uint16_t)((c<<1)^0x1021):(uint16_t)(c<<1);}return c;}size_t protocol_encode(uint8_t*o,size_t cap,uint32_t seq,uint32_t ts,float rms,float t,float a,uint8_t f,uint8_t h){if(!o||cap<FRAME_SIZE)return 0;o[0]=0xA5;o[1]=1;put32(o+2,seq);put32(o+6,ts);memcpy(o+10,&rms,4);memcpy(o+14,&t,4);memcpy(o+18,&a,4);o[22]=(uint8_t)((f&7)|((h&3)<<3));uint16_t crc=protocol_crc16(o,23);o[23]=(uint8_t)crc;o[24]=(uint8_t)(crc>>8);return FRAME_SIZE;}int protocol_decode(const uint8_t*i,size_t n,uint32_t*s,float*r){if(!i||n!=FRAME_SIZE||i[0]!=0xA5||i[1]!=1)return -1;uint16_t received=(uint16_t)i[23]|((uint16_t)i[24]<<8);if(received!=protocol_crc16(i,23))return -2;if(s)*s=get32(i+2);if(r)memcpy(r,i+10,4);return 0;}
